insert into public.data_center_provider_coverage(marker_id,scopes,provider_key,value_status,source_keys,last_verified_at,notes,provider_kind,source_fields,calculation_key,freshness_seconds,cache_policy,bulk_capable) values
('budget.debt_service_share',array['municipality'],'workbench-hydrate','live',array['nj-dca-budget'],now(),'NJ DCA User-Friendly Budget debt payment divided by current appropriation.','authoritative_reference',array['budget.debt_service_share'],'nj-dca-budget',86400,'refresh_on_demand',true),
('budget.net_debt_pct',array['municipality'],'workbench-hydrate','live',array['nj-dca-budget'],now(),'NJ DCA User-Friendly Budget net debt percentage.','authoritative_reference',array['budget.net_debt_pct'],'nj-dca-budget',86400,'refresh_on_demand',true),
('appeals.latest_total',array['county'],'workbench-hydrate','live',array['nj-tax-court-appeals'],now(),'Latest published county property-tax appeal filings from NJ Division of Taxation summary.','authoritative_reference',array['latest.total'],'nj-tax-court-appeals',86400,'refresh_on_demand',true),
('appeals.latest_assessed_appealed',array['county'],'workbench-hydrate','live',array['nj-tax-court-appeals'],now(),'Latest published county assessed value under appeal.','authoritative_reference',array['latest.assessed_appealed'],'nj-tax-court-appeals',86400,'refresh_on_demand',true),
